import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Limit } from '../types'
import { describeLimit, DIVIDER, formatBar, formatLine, RESET_MARK, TITLE } from './limits'
import type { Reading } from './limits'

const REFRESH_MS = 60_000
const NO_LIMITS = 'plan limits: none reported yet'

const limits = atom({ plugin: 'plan-limits', key: 'limits' } as const, [] as Limit[])
const now = atom({ plugin: 'plan-limits', key: 'now' } as const, 0)

const readingsOf = (all: readonly Limit[], at: number): Reading[] =>
  all.map(limit => describeLimit(limit, at)).filter(reading => reading !== undefined)

type Display = { placement: string; isStatus: boolean; barWidth: number }

async function refresh($: EngineInterface, display: Display, latest?: readonly Limit[]) {
  if(latest !== undefined) {
    await update($, limits, () => [...latest])
  }

  await update($, now, () => Date.now())

  if(display.isStatus) {
    const readings = readingsOf(await read($, limits), await read($, now))
    $.ui.status(readings.length === 0 ? NO_LIMITS : formatLine(readings, display.barWidth))
  }
}

type Elements = ReturnType<EngineInterface['ui']['resolve']>
type Colors = Record<Reading['level'], string>

const limitsTree = (readings: readonly Reading[], barWidth: number, colors: Colors, { Box, Text }: Elements) => (
  <Box gap={1}>
    <Text dimColor>{TITLE}</Text>
    {readings.map(reading => {
      const bar = formatBar(reading.percent, barWidth)

      return (
        <Box key={reading.label} gap={1}>
          <Text dimColor>{DIVIDER}</Text>
          <Text>{reading.label}</Text>
          <Box>
            <Text color={colors[reading.level]}>{bar.filled}</Text>
            <Text dimColor>{bar.empty}</Text>
          </Box>
          <Text color={colors[reading.level]} bold>{`${reading.percent}%`}</Text>
          {reading.resetsIn === undefined ? null : <Text dimColor>{`${RESET_MARK}${reading.resetsIn}`}</Text>}
          {reading.isOnPaceToRunOut ? <Text color={colors.hot}>on pace to run out</Text> : null}
        </Box>
      )
    })}
  </Box>
)

export const register: Register = (on, options) => {
  const placement = String(options.placement ?? 'hint')
  const isStatus = placement === 'status'
  const barWidth = Number(options.barWidth ?? 5)
  const display = { placement, isStatus, barWidth }
  const colors = {
    ok: String(options.okColor ?? 'green'),
    warn: String(options.warnColor ?? 'yellow'),
    hot: String(options.hotColor ?? 'red'),
  }

  on('session.start', async ($, e, next) => {
    const result = await next(e)

    if(!isStatus) {
      $.ui.status(undefined)
    }

    await refresh($, display, (await $.session.usage()).rateLimits)
    $.clock.every(REFRESH_MS, () => void refresh($, display))

    return result
  })

  on('session.measure', async ($, e, next) => {
    if(e.changed.includes('rateLimits')) {
      await refresh($, display, e.rateLimits)
    }

    return next(e)
  })

  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    const line = await next(e)
    const readings = readingsOf(await read($, limits), await read($, now))

    if(placement !== 'hint' || readings.length === 0) {
      return line
    }

    const elements = $.ui.resolve(e)

    return <elements.Box gap={2}>{line}{limitsTree(readings, barWidth, colors, elements)}</elements.Box>
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const readings = readingsOf(await read($, limits), await read($, now))

    if(placement !== 'band' || e.props.hasSurvey || readings.length === 0) {
      return next(e)
    }

    return limitsTree(readings, barWidth, colors, $.ui.resolve(e))
  })
}

