import type { Limit } from '../types'

const MINUTE = 60_000
const HOUR = 60 * MINUTE
const DAY = 24 * HOUR
const MIN_ELAPSED_FOR_PACE = 0.05
const HOT_PERCENT = 90
const WARN_PERCENT = 70
const HOT_PACE = 100
const WARN_PACE = 85

const WINDOWS: Record<string, { label: string; ms: number }> = {
  five_hour: { label: 'session', ms: 5 * HOUR },
  seven_day: { label: 'weekly', ms: 7 * DAY },
}

export type Level = 'ok' | 'warn' | 'hot'

export type Reading = {
  label: string
  percent: number
  resetsIn?: string
  level: Level
  isOnPaceToRunOut: boolean
}

const EIGHTHS = ['', '▏', '▎', '▍', '▌', '▋', '▊', '▉']

export const formatBar = (percent: number, width: number): { filled: string; empty: string } => {
  const cells = Math.max(1, Math.round(width))
  const eighths = Math.round((Math.min(100, Math.max(0, percent)) / 100) * cells * 8)
  const full = Math.floor(eighths / 8)
  const partial = EIGHTHS[eighths % 8] ?? ''
  const used = full + (partial === '' ? 0 : 1)

  return { filled: '█'.repeat(full) + partial, empty: '·'.repeat(cells - used) }
}

export const formatDuration = (ms: number): string => {
  const minutes = Math.max(0, Math.round(ms / MINUTE))
  const hours = Math.floor(minutes / 60)
  const days = Math.floor(hours / 24)

  if(days > 0) {
    return `${days}d ${hours % 24}h`
  }

  return hours > 0 ? `${hours}h ${minutes % 60}m` : `${minutes}m`
}

const projectedPercent = (percent: number, msLeft: number, windowMs: number): number => {
  const elapsed = 1 - msLeft / windowMs

  return elapsed > MIN_ELAPSED_FOR_PACE ? percent / elapsed : 0
}

const levelOf = (percent: number, projected: number): Level => {
  if(percent >= HOT_PERCENT || projected >= HOT_PACE) {
    return 'hot'
  }

  return percent >= WARN_PERCENT || projected >= WARN_PACE ? 'warn' : 'ok'
}

export const describeLimit = (limit: Limit, now: number): Reading | undefined => {
  const window = WINDOWS[limit.kind]

  if(window === undefined) {
    return undefined
  }

  const msLeft = limit.resetsAt === undefined ? undefined : Date.parse(limit.resetsAt) - now
  const hasReset = msLeft !== undefined && msLeft > 0
  const projected = hasReset ? projectedPercent(limit.percentUsed, msLeft, window.ms) : 0

  return {
    label: window.label,
    percent: Math.round(limit.percentUsed),
    resetsIn: hasReset ? formatDuration(msLeft) : undefined,
    level: levelOf(limit.percentUsed, projected),
    isOnPaceToRunOut: projected >= HOT_PACE,
  }
}

export const TITLE = 'Claude'
export const DIVIDER = '│'
export const RESET_MARK = '↻'

export const formatLine = (readings: readonly Reading[], barWidth: number): string =>
  [TITLE, ...readings.map(reading => {
    const bar = formatBar(reading.percent, barWidth)
    const resets = reading.resetsIn === undefined ? '' : ` ${RESET_MARK}${reading.resetsIn}`
    const pace = reading.isOnPaceToRunOut ? ' · on pace to run out' : ''

    return `${reading.label} ${bar.filled}${bar.empty} ${reading.percent}%${resets}${pace}`
  })].join(` ${DIVIDER} `)

